		var b = $.glue.popover.icon_button(t[1], t[2]);
		b.style.width = '22px';
		b.style.height = '22px';
		b.classList.add('glue-font-style');
		b.dataset.fmt = t[0];
		b.addEventListener('click', function() {
			if (run_active()) {
				if (text_strip_render) {
					text_strip_toggle(text_strip_render, t[0]);
				}
			} else {
				t[3]();
				save();
				sync();
			}
		});
		toggles[t[0]] = b;
